async function cropFile(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('Usa JPG, PNG o WebP de menos de 15 MB.');const values=[0,1,2,3].map(i=>Number($('#crop-'+i).value));const [x,y,w,h]=values;if(values.some(v=>!Number.isFinite(v)||v<0)||w<=0||h<=0||x+w>100.01||y+h>100.01)throw Error('El recorte debe quedar dentro del 100% de la imagen.');const bitmap=await createImageBitmap(file);const width=bitmap.width*w/100,height=bitmap.height*h/100,scale=Math.min(1,1600/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(bitmap,bitmap.width*x/100,bitmap.height*y/100,width,height,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.9);}

function renderPriorities(){const term=norm($('#priority-search').value),only=$('#priority-filter').checked;const matches=catalog.filter(x=>norm(x.scientificName).includes(term)&&(!only||info(x).count>0)).sort((a,b)=>info(b).count-info(a).count||a.scientificName.localeCompare(b.scientificName));$('#priority-table').innerHTML=matches.slice(0,priorityLimit).map(item=>{const p=info(item),o=data.overrides[item.id];return '<article class="priority-row" data-priority-id="'+esc(item.id)+'"><h3>'+esc(item.scientificName)+'</h3><p class="help">'+(p.manual?'Edición personal':'Historial documentado')+' · peso de selección ×'+p.weight.toFixed(2)+' · objetivo de recuerdo '+Math.round(p.retention*100)+'%</p><div class="priority-fields"><label>Peso de prioridad<input name="count" type="number" min="0" max="30" step="1" value="'+p.count+'"></label><label>Años<input name="years" placeholder="2021,2025" value="'+esc((o?.years||p.years).join(','))+'"></label><label>Fuente / referencia<input name="source" value="'+esc(o?.source||'')+'"></label><label>Nota<input name="note" value="'+esc(o?.note||'')+'"></label></div><div class="actions"><button data-save-priority class="primary-button">Guardar</button><button data-reset-priority class="text-button">Usar historial</button></div><details><summary>'+p.evidence.length+' evidencias · distinguir nombres, fórmulas y fotos</summary><ul>'+p.evidence.map(e=>'<li>'+e.year+' · '+esc(e.context)+' · pág. '+esc(e.page??'—')+' · '+link(e.source,'Enunciado / referencia pública')+(e.sourceFile?'<br><strong>Clave académica:</strong> '+esc(e.sourceFile)+' · PDF p. '+esc(e.solutionPage)+' · opción '+esc(e.option)+' · nº '+esc(e.question)+(e.sourceName!==e.name?' · nombre impreso: '+esc(e.sourceName):''):'')+' '+esc(e.note||'')+'</li>').join('')+'</ul></details></article>';}).join('')||'<p>No hay resultados. Desmarca «Solo prioritarias» para añadir una entrada.</p>';$('#priority-more').hidden=matches.length<=priorityLimit;}
