async function sync(){
 if(!client)return;if(syncing){syncRequested=true;return;}syncing=true;
 let owner=null,revision=null;
 try{
  const {data:auth,error:authError}=await client.auth.getSession();if(authError)throw authError;
  if(!auth.session){$('#sync-status').textContent='Accede con tu correo para sincronizar.';return;}
  owner=auth.session.user.id;if(account!==owner&&!await activateAccount(owner))return;
  revision=accountRevision;const state=data;
  $('#sync-account').textContent='Cuenta: '+auth.session.user.email;$('#sync-status').textContent='Sincronizando…';
  const result=await synchronizeAccount(client,{userId:owner,state,isCurrent:()=>account===owner&&data===state&&accountRevision===revision,persist:value=>write('account:'+owner,value)});
  if(result.cancelled)return;
  $('#sync-status').textContent='Sincronizado · '+new Date().toLocaleTimeString();applyPreferences();renderStats();renderPriorities();try{await community.refresh();}catch(error){$('#community-status').textContent='Progreso sincronizado. Aportaciones compartidas pendientes: '+error.message;}
 }catch(e){if(revision===null||accountRevision===revision)$('#sync-status').textContent='Guardado en este dispositivo. Pendiente de sincronizar: '+e.message;throw e;}
 finally{syncing=false;if(syncRequested){syncRequested=false;setTimeout(()=>sync().catch(()=>{}),0);}}
}
async function initCloud(){
 try{
  const config=publicCloudConfig(supabaseConfig);if(!config)return;
  const {createClient}=await import('./vendor/supabase.mjs');client=createClient(config.url,config.key);
  client.auth.onAuthStateChange((event,session)=>{setTimeout(async()=>{
   try{if(event==='SIGNED_OUT'){await activateAccount('guest');$('#sync-account').textContent='Estudio local · sesión cerrada';}
    else if(session&&['INITIAL_SESSION','SIGNED_IN','TOKEN_REFRESHED','USER_UPDATED'].includes(event)){await activateAccount(session.user.id);$('#sync-account').textContent='Cuenta: '+session.user.email;await sync();}}
   catch(e){$('#sync-status').textContent='Guardado aquí. '+e.message;}
  },0);});
  const {data:auth,error}=await client.auth.getSession();if(error)throw error;
  if(auth.session){await activateAccount(auth.session.user.id);await sync();}
  else{await activateAccount('guest');$('#sync-status').textContent='Introduce el correo de tu cuenta autorizada para acceder.';}
 }catch(e){$('#sync-status').textContent='Estudio local disponible. Sincronización pendiente: '+e.message;}
}

